//go:build ignore

// fix_kiota_backing_store patches Go code generated by Kiota with
// --backing-store so that collections of composed-type (oneOf/anyOf) wrappers
// compile. Kiota 1.38.0 emits them as value types instead of interfaces:
//
//	res := make([]Foo_included, len(val))
//	res[i] = *(v.(*Foo_included))
//	...
//	temp := v
//	cast[i] = serialization.Parsable(&temp)
//
// which is rewritten to the form Kiota emits without --backing-store:
//
//	res := make([]Foo_includedable, len(val))
//	res[i] = v.(Foo_includedable)
//	...
//	cast[i] = v.(serialization.Parsable)
//
// Remove once the upstream Kiota bug is fixed.
//
// Usage: go run scripts/fix_kiota_backing_store.go <dir>
package main

import (
	"fmt"
	"go/format"
	"io/fs"
	"os"
	"path/filepath"
	"regexp"
	"strings"
)

var (
	// Only exported (capitalized) types: primitive collections such as
	// *(v.(*string)) are correct and must be left alone.
	deserializeRe = regexp.MustCompile(
		`res := make\(\[\]([A-Z]\w*), len\(val\)\)(\s+for i, v := range val \{\s+if v != nil \{\s+)res\[i\] = \*\(v\.\(\*([A-Z]\w*)\)\)`)

	// Taking the address of an interface value is never a valid Parsable.
	serializeRe = regexp.MustCompile(
		`temp := v(\s+)cast\[i\] = (\w+)\.Parsable\(&temp\)`)

	// Kiota declares `type Fooable interface` for every model (including
	// composed wrappers), but not for enums, which are legitimately value
	// types and must not be rewritten.
	interfaceRe = regexp.MustCompile(`(?m)^type (\w+)able interface\b`)
)

func fix(src string, models map[string]bool) string {
	src = deserializeRe.ReplaceAllStringFunc(src, func(m string) string {
		g := deserializeRe.FindStringSubmatch(m)
		typ, body, assertTyp := g[1], g[2], g[3]
		if typ != assertTyp || !models[typ] {
			return m
		}
		return fmt.Sprintf("res := make([]%sable, len(val))%sres[i] = v.(%sable)", typ, body, typ)
	})
	src = serializeRe.ReplaceAllString(src, "cast[i] = v.($2.Parsable)")
	return src
}

func main() {
	if len(os.Args) != 2 {
		fmt.Fprintln(os.Stderr, "usage: go run scripts/fix_kiota_backing_store.go <dir>")
		os.Exit(2)
	}

	// Pass 1: collect every type that has a Kiota model interface. Wrappers
	// used by request builders live in other packages, so scan the whole tree.
	sources := map[string]string{}
	models := map[string]bool{}
	err := filepath.WalkDir(os.Args[1], func(path string, d fs.DirEntry, err error) error {
		if err != nil || d.IsDir() || !strings.HasSuffix(path, ".go") {
			return err
		}
		raw, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		sources[path] = string(raw)
		for _, m := range interfaceRe.FindAllStringSubmatch(string(raw), -1) {
			models[m[1]] = true
		}
		return nil
	})
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}

	// Pass 2: rewrite.
	var patched int
	for path, raw := range sources {
		fixed := fix(raw, models)
		if fixed == raw {
			continue
		}
		formatted, err := format.Source([]byte(fixed))
		if err != nil {
			fmt.Fprintf(os.Stderr, "%s: %v\n", path, err)
			os.Exit(1)
		}
		info, err := os.Stat(path)
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		if err := os.WriteFile(path, formatted, info.Mode().Perm()); err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		patched++
	}
	fmt.Printf("fix_kiota_backing_store: patched %d file(s)\n", patched)
}
